// CPython merges a call's keywords (explicit and **) into one dict before it binds anything, and
// the first key that arrives twice raises TypeError. A keyword list is almost always tiny, so it is
// scanned in place; only a very large ** dict goes through a set.
#[inline]
fn kw_dup(k: &[(Sym, V)]) -> Option<Sym> {
    if k.len() < 2 {
        return None;
    }
    if k.len() <= 16 {
        for i in 0..k.len() {
            for j in (i + 1)..k.len() {
                if k[i].0 == k[j].0 {
                    return Some(k[i].0);
                }
            }
        }
        return None;
    }
    let mut seen: std::collections::HashSet<Sym> = std::collections::HashSet::with_capacity(k.len());
    for (n, _) in k {
        if !seen.insert(*n) {
            return Some(*n);
        }
    }
    None
}

